// ───── listMarkets — List Lista Lending markets ─────
//
// [FILLED v0.1.3] Delegates to the source CLI. Filters out SmartLending
// (zone === 3) and fixed-term (termType === 1) markets per upstream behavior
// — those aren't supported by the write-side wrappers, so listing them would
// surface markets the user can't actually act on.
async function listMarkets(params: {
  chain?: string;
  page?: number;
  pageSize?: number;
  sort?: 'apy' | 'liquidity' | 'tvl' | string;
  order?: 'asc' | 'desc';
  loans?: string[];        // filter by loan-token symbols, e.g. ['USDT', 'USD1']
  collaterals?: string[];  // filter by collateral-token symbols
  keyword?: string;
}) {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain, caip2: chainId } = chainResult;

  // Runtime hint for the LLM: invoke the source CLI and parse stdout JSON.
  //   node ~/.claude/skills/lista-lending/dist/cli/cli.bundle.mjs markets \
  //     --chain <chainId> [--sort <sort>] [--order <order>] [--page <page>] \
  //     [--page-size <pageSize>] [--loans <comma-list>] [--collaterals <comma-list>] \
  //     [--keyword <keyword>]
  // The CLI already applies the SmartLending/fixed-term filter (see
  // src/commands/markets.ts), so the returned list is safe to surface to the user.
  //
  // Always include this user-facing note when presenting the result:
  //   "Smart Lending and fixed-term market operations are currently not supported in this skill.
  //    For full functionality, please use the Lista website."
  const result = await listaCli.run('markets', {
    chain: chainId,
    sort: params.sort,
    order: params.order,
    page: params.page,
    pageSize: params.pageSize,
    loans: params.loans?.join(','),
    collaterals: params.collaterals?.join(','),
    keyword: params.keyword,
  });

  return {
    status: 'ok',
    chain,
    note: 'Smart Lending and fixed-term markets are filtered out.',
    data: result,  // pagination + market[] with collateral/loan/LLTV/borrowRate/liquidity
  };
}

