// ───── getHoldings — User position snapshot across vaults + markets ─────
//
// [FILLED v0.1.3] Returns vault positions + market positions. Market
// positions carry isSmartLending / isFixedTerm / isActionable flags
// (computed upstream from zone/termType). Caller is responsible for the
// health label mapping (Healthy/Warning/Risk) per the SKILL.md guidelines.
async function getHoldings(params: {
  address: string;                              // wallet address to query
  chain?: string;
  scope?: 'all' | 'vault' | 'market' | 'selected';
}) {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain, caip2: chainId } = chainResult;
  const scope = params.scope ?? 'all';

  if (!params.address) {
    return {
      status: 'error' as const,
      error_code: 'MISSING_ADDRESS',
      message: '`address` is required (the wallet whose holdings you want to query).',
    };
  }

  // Runtime hint:
  //   node ~/.claude/skills/lista-lending/dist/cli/cli.bundle.mjs holdings \
  //     --address <address> --chain <chainId> --scope <scope>
  // Output shape (matches upstream):
  //   { vaultPositions: [{vault, chain, deposited, depositedUsd, apy, walletBalance}, ...],
  //     marketPositions: [{market, chain, collateralUsd, borrowedUsd, ltv, health,
  //                        zone, termType, isSmartLending, isFixedTerm, isActionable}, ...],
  //     summary: { totalVaults, totalMarkets, actionableMarkets, unsupportedMarkets } }
  const result = await listaCli.run('holdings', {
    address: params.address,
    chain: chainId,
    scope,
  });

  return {
    status: 'ok',
    chain,
    scope,
    note:
      'Lista API indexer may lag 30-60s behind on-chain state. ' +
      'For real-time vault position state immediately after a deposit/withdraw, ' +
      'use getVaultPosition({vaultAddress, walletAddress}) instead.',
    data: result,
  };
}

// ───── getVaultPosition — Real-time on-chain vault position (no indexer) ─────
//
// [ADDED v0.1.6] Bypasses the Lista API indexer by reading ERC-4626 share
// balance + underlying value directly from the vault contract via RPC.
// Use immediately after a deposit/withdraw when getHoldings hasn't caught up,
// or when you want guaranteed fresh state.
//
// Required params: { vaultAddress, walletAddress }
// Optional params: { chain }  // 'bsc' (default) or 'ethereum'
async function getVaultPosition(params: {
  vaultAddress: string;
  walletAddress: string;
  chain?: string;
}) {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain, id: chainId } = chainResult;
  const { vaultAddress, walletAddress } = params;

  const targetError =
    validateEvmAddress(vaultAddress, 'vaultAddress') ??
    validateEvmAddress(walletAddress, 'walletAddress');
  if (targetError) return targetError;

  // Read shares + symbol + underlying value (3 parallel RPC calls).
  const [shares, symbol, vaultInfo] = await Promise.all([
    erc4626.balanceOf(vaultAddress, walletAddress, chainId),
    erc4626.symbol(vaultAddress, chainId),
    listaSdk.getVaultInfo(chainId, vaultAddress),
  ]);
  const assetDecimals = (vaultInfo as any).assetInfo.decimals;
  const assetSymbol = (vaultInfo as any).assetInfo.symbol;
  const underlying = shares > 0n
    ? await erc4626.convertToAssets(vaultAddress, shares, chainId)
    : 0n;

  return {
    status: 'ok',
    chain,
    data: {
      vaultAddress,
      walletAddress,
      shares: {
        raw: shares.toString(),
        formatted: formatUnits(shares, assetDecimals),
        symbol,
      },
      underlying: {
        raw: underlying.toString(),
        formatted: formatUnits(underlying, assetDecimals),
        symbol: assetSymbol,
      },
      hasPosition: shares > 0n,
    },
  };
}

// ───── simulateBorrow — Dry-run borrow capacity check (no signature) ─────
//
// [ADDED + FILLED v0.1.3] Wraps Lista's existing buildBorrowSimulationPayload —
// returns projected loanable, safe borrow cap (95% of loanable), and
// optionally the after-supply loanable if `simulateSupply` is provided.
// Use before calling buildBorrow to surface capacity to the user.
async function simulateBorrow(params: {
  marketId: string;
  walletAddress: string;
  chain?: string;
  simulateSupply?: string;  // optional hypothetical supply amount in UI units
}) {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain, caip2: chainId } = chainResult;

  // Runtime hint:
  //   node ~/.claude/skills/lista-lending/dist/cli/cli.bundle.mjs borrow --simulate \
  //     --market <marketId> --chain <chainId> --wallet-address <walletAddress> \
  //     [--simulate-supply <amount>]
  // Output (matches upstream buildBorrowSimulationPayload):
  //   { status, action: 'simulate', market, chain,
  //     collateral: {symbol, ...}, loan: {symbol, ...},
  //     current: { loanable, safeBorrow },
  //     afterSupply?: { loanable, safeBorrow, supplyAmount } }
  const result = await listaCli.run('borrow', {
    simulate: true,
    market: params.marketId,
    chain: chainId,
    walletAddress: params.walletAddress,
    simulateSupply: params.simulateSupply,
  });

  return {
    status: 'ok',
    chain,
    data: result,
  };
}

// ───── simulateRepay — Dry-run repay impact check (no signature) ─────
//
// [ADDED + FILLED v0.1.3] Wraps Lista's existing buildRepaySimulationPayload —
// returns the projected position after repay (new health factor, debt
// remaining). Use before calling buildRepay to confirm impact.
async function simulateRepay(params: {
  marketId: string;
  walletAddress: string;
  amount?: string;
  repayAll?: boolean;
  chain?: string;
}) {
  const chainResult = resolveChain(params.chain);
  if ('status' in chainResult) return chainResult;
  const { name: chain, caip2: chainId } = chainResult;

  if (!params.amount && !params.repayAll) {
    return {
      status: 'error' as const,
      error_code: 'MISSING_AMOUNT',
      message: 'Either `amount` or `repayAll: true` must be provided.',
    };
  }

  // Runtime hint:
  //   node ~/.claude/skills/lista-lending/dist/cli/cli.bundle.mjs repay --simulate \
  //     --market <marketId> --chain <chainId> --wallet-address <walletAddress> \
  //     (--amount <amount> | --repay-all)
  // Output (matches upstream buildRepaySimulationPayload):
  //   { status, action: 'simulate', market, chain,
  //     currentDebt, estimatedRepay, afterRepay: { debt, health, ... } }
  const result = await listaCli.run('repay', {
    simulate: true,
    market: params.marketId,
    chain: chainId,
    walletAddress: params.walletAddress,
    amount: params.amount,
    repayAll: params.repayAll,
  });

  return {
    status: 'ok',
    chain,
    data: result,
  };
}

// ============================================================================
// Public exports — every tool reachable by the Agent must be here
