export {
  // Transaction tools (return pending_sign | ToolError)
  buildDeposit,
  buildWithdraw,
  buildSupply,
  buildBorrow,
  buildRepay,
  buildMarketWithdraw,
  // Read-only tools (return raw JSON; never trigger signing)
  listMarkets,
  listVaults,
  getHoldings,
  getVaultPosition,
  simulateBorrow,
  simulateRepay,
};
